-- Typed audiences constrain staff too. Owners/curators retain their specific
-- review/source authority; a generic teacher role is not another class's grant.
CREATE FUNCTION phase10_catalog_staff_scope(s TEXT,scope TEXT,section_id TEXT,class_id TEXT,student_id TEXT,u TEXT) RETURNS BOOLEAN AS $$
 SELECT EXISTS(SELECT 1 FROM "Membership" m JOIN "School" school ON school."id"=m."schoolId" AND school."isActive" WHERE m."schoolId"=s AND m."userId"=u AND m."isActive" AND m."role" IN ('SCHOOL_SUPER_ADMIN','SCHOOL_ADMIN','TEACHER','FORM_TEACHER','HEAD_OF_SECTION','PRINCIPAL') AND (m."role"='SCHOOL_SUPER_ADMIN' OR scope='SCHOOL' OR EXISTS(
 SELECT 1 FROM "SchoolClass" room JOIN "SchoolSection" section ON section."schoolId"=room."schoolId" AND section."id"=room."sectionId" AND section."isActive" WHERE room."schoolId"=s AND room."isActive" AND ((scope='SECTION' AND room."sectionId"=section_id) OR (scope='CLASS' AND room."id"=class_id) OR (scope='STUDENT' AND EXISTS(SELECT 1 FROM "StudentRecord" p JOIN "StudentEnrollment" e ON e."schoolId"=p."schoolId" AND e."studentId"=p."id" AND e."status"='ACTIVE' JOIN "AcademicSession" session ON session."schoolId"=e."schoolId" AND session."id"=e."sessionId" AND session."status"='ACTIVE' WHERE p."schoolId"=s AND p."id"=student_id AND p."status"='ENROLLED' AND e."classId"=room."id"))) AND (
 EXISTS(SELECT 1 FROM "TeacherClassSubjectAssignment" a JOIN "AcademicSession" session ON session."schoolId"=a."schoolId" AND session."id"=a."sessionId" AND session."status"='ACTIVE' JOIN "Subject" subject ON subject."schoolId"=a."schoolId" AND subject."id"=a."subjectId" AND subject."isActive" WHERE a."schoolId"=s AND a."membershipId"=m."id" AND a."classId"=room."id" AND a."status"='ACTIVE' AND m."role" IN ('TEACHER','FORM_TEACHER')) OR
 EXISTS(SELECT 1 FROM "FormTeacherResponsibility" f JOIN "AcademicSession" session ON session."schoolId"=f."schoolId" AND session."id"=f."sessionId" AND session."status"='ACTIVE' WHERE f."schoolId"=s AND f."membershipId"=m."id" AND f."classId"=room."id" AND f."status"='ACTIVE' AND m."role" IN ('TEACHER','FORM_TEACHER')) OR
 EXISTS(SELECT 1 FROM "ScopeGrant" g WHERE g."membershipId"=m."id" AND g."type"='SECTION' AND g."verified" AND g."scopeId"=section."id" AND ((m."role"='HEAD_OF_SECTION' AND section."stage"='PRIMARY') OR (m."role"='PRINCIPAL' AND section."stage"='SECONDARY')))
 ))));
$$ LANGUAGE sql STABLE;
CREATE OR REPLACE FUNCTION can_read_library_catalog(s TEXT,r UUID,u TEXT) RETURNS BOOLEAN AS $$
 SELECT EXISTS(SELECT 1 FROM "LibraryCatalogRelease" release JOIN "LibraryCatalogEntry" c ON c."schoolId"=release."schoolId" AND c."id"=release."entryId"
 WHERE release."schoolId"=s AND release."id"=r AND phase10_catalog_curator(s,c."curatorUserId",c."curatorMembershipId")
 AND phase10_owner(s,release."actorUserId")
 AND EXISTS(SELECT 1 FROM "LibraryCatalogReview" review WHERE review."schoolId"=s AND review."entryId"=c."id" AND review."revision"=release."revision" AND review."action"='APPROVE' AND phase10_owner(s,review."actorUserId"))
 AND NOT EXISTS(SELECT 1 FROM "LibraryCatalogWithdrawal" w WHERE w."schoolId"=s AND w."releaseId"=release."id")
 AND NOT EXISTS(SELECT 1 FROM "LibraryCatalogRelease" newer WHERE newer."schoolId"=s AND newer."entryId"=c."id" AND newer."ordinal">release."ordinal")
 AND (u=c."curatorUserId" OR phase10_catalog_staff_scope(s,release."scope",release."sectionId",release."classId",release."studentId",u) OR EXISTS(SELECT 1 FROM "Membership" m JOIN "StudentAccountLink" b ON b."schoolId"=s AND b."studentMembershipId"=m."id" JOIN "StudentRecord" p ON p."schoolId"=s AND p."id"=b."studentId" AND p."status"='ENROLLED' JOIN "StudentEnrollment" e ON e."schoolId"=s AND e."studentId"=p."id" AND e."status"='ACTIVE' JOIN "AcademicSession" session ON session."schoolId"=s AND session."id"=e."sessionId" AND session."status"='ACTIVE' JOIN "SchoolClass" room ON room."schoolId"=s AND room."id"=e."classId" AND room."isActive" JOIN "SchoolSection" section ON section."schoolId"=s AND section."id"=room."sectionId" AND section."isActive" WHERE m."schoolId"=s AND m."userId"=u AND m."isActive" AND m."role"='STUDENT' AND NOT EXISTS(SELECT 1 FROM "StudentAccountLinkRevocation" v WHERE v."schoolId"=s AND v."linkId"=b."id") AND (release."scope"='SCHOOL' OR release."sectionId"=section."id" OR release."classId"=room."id" OR release."studentId"=p."id"))));
$$ LANGUAGE sql STABLE;
